B.aca=new A.dG("q_riverbloom","Riverbloom","quest",null,"grey","",B.aN,0,0,"any","A pale river flower. Mira needs three.","quest",0,!1)
B.acb=new A.dG("q_bent_antler","Snapped Antler","quest",null,"grey","",B.aN,0,0,"any","Broken running, not fighting.","quest",0,!1)
B.abY=new A.dG("q_torn_satchel","Torn Satchel","quest",null,"grey","",B.aN,0,0,"any","Renn's. A sealed letter is still inside.","quest",0,!1)
B.abZ=new A.dG("q_sealed_letter","Sealed Letter","quest",null,"grey","",B.aN,0,0,"any","Pell says it is about grain.","quest",0,!1)
B.ac3=new A.dG("q_folded_reply","Folded Reply","quest",null,"grey","",B.aN,0,0,"any","For Pell. It is not about grain either.","quest",0,!1)
B.acc=new A.dG("q_ferry_bell","Dented Bell","quest",null,"grey","",B.aN,0,0,"any","Small and brass. It belongs at the landing.","quest",0,!1)
